import{_ as t}from"./chunks/2025-03-10_20-17-27.OVsGDLx4.js";import{_ as o,c as i,o as r,ae as n}from"./chunks/framework.CQ8DW7XN.js";const m=JSON.parse('{"title":"Prerequisites","description":"","frontmatter":{},"headers":[],"relativePath":"docs/neo/prerequisites.md","filePath":"docs/neo/prerequisites.md"}'),a={name:"docs/neo/prerequisites.md"};function l(s,e,c,u,p,h){return r(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h1><h3 id="software-requirements" tabindex="-1">Software Requirements <a class="header-anchor" href="#software-requirements" aria-label="Permalink to &quot;Software Requirements&quot;">​</a></h3><p>The software is footprint agnostic, running both in on-prem and in the cloud, connecting to NetApp and non-NetApp storage appliances.</p><ul><li>A container Runtime: <ul><li>Deployable on Docker/Podman with a Compose file</li><li>Deployable on Kubernetes cluster with a Helm Chart</li></ul></li><li>A database server: <ul><li>Either Postgres or MySQL</li><li>An optional Postgres configuration is provided for testing purposes only</li></ul></li><li>A Microsoft M365 Copilot License is required if connecting to MS Graph</li></ul><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p>AWS ECS (Fargate) is NOT supported. This is due to the containers being unable to mount shares to the container(s) - a critical requirement of NetApp Neo.</p></div><h3 id="network-requirements" tabindex="-1">Network Requirements <a class="header-anchor" href="#network-requirements" aria-label="Permalink to &quot;Network Requirements&quot;">​</a></h3><ul><li><strong>Port 8080</strong> open for internal management of the connector</li><li><strong>Port 445</strong> open for SMB file share access</li><li>SMB File Share(s) must be routable to the connector</li><li><strong>Port 443</strong> open for outbound traffic when connecting to M365 Copilot Graph API</li></ul><h2 id="m365-copilot-use-case" tabindex="-1">M365 Copilot Use Case <a class="header-anchor" href="#m365-copilot-use-case" aria-label="Permalink to &quot;M365 Copilot Use Case&quot;">​</a></h2><p>The Neo Connector has to be registered as an Application within your M365 tenant.</p><h3 id="register-the-connector-in-azure-entra" tabindex="-1">Register the connector in Azure Entra <a class="header-anchor" href="#register-the-connector-in-azure-entra" aria-label="Permalink to &quot;Register the connector in Azure Entra&quot;">​</a></h3><p>In order for the connector to be able to securely communicate with M365 Copilot.</p><p><img src="'+t+'" alt="Select App Registration in the Add menu in Microsoft Azure Entra"></p><ol><li>Navigate to the Azure Entra portal and select &quot;Add&quot; and select the &quot;App Registration&quot; option.</li><li>Fill in the required fields and click &quot;Register&quot;. (No Redirect URI is required)</li><li>Copy the Application (client) ID and Directory (tenant) ID from the Overview page.</li><li>Navigate to the &quot;API permissions&quot; page and select &quot;Add a permission&quot;.</li><li>Select &quot;Microsoft Graph&quot; and then &quot;Application permissions&quot;.</li><li>Search for &quot;ExternalConnection.ReadWrite.OwnedBy&quot; and select the checkbox.</li><li>Search for &quot;ExternalItem.ReadWrite.OwnedBy&quot; and select the checkbox.</li><li>Search for &quot;User.Read&quot; and select the checkbox.</li><li>Search for &quot;User.Read.All&quot; and select the checkbox.</li><li>Search for &quot;Group.Read.All&quot; and select the checkbox</li><li>Click &quot;Add permissions&quot;.</li><li>Click &quot;Graph admin consent for (tenant)&quot; and click &quot;Yes&quot;.</li><li>Navigate to the &quot;Certificates &amp; secrets&quot; page and click &quot;New client secret&quot;.</li><li>Fill in the required fields and click &quot;Add&quot;.</li><li>Copy the value of the client secret.</li></ol><p>You have successfully registered the connector in Azure ENTRA. You will need the Application ID, Directory ID, and Client Secret for the next steps.</p>',14)])])}const f=o(a,[["render",l]]);export{m as __pageData,f as default};
